from __future__ import annotations

import sys
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
if str(ROOT) not in sys.path:
    sys.path.insert(0, str(ROOT))

from Projects.Applications.Universe.python.python_bridge import execute


def test_universe_python_bridge_service_renders_visibility():
    payload = {
        "menu": {
            "items": [
                {"key": "1", "label": "Bootstrap", "visibility_condition": "bootstrap_mode"},
                {"key": "2", "label": "Edit", "visibility_condition": "initialized_and_vile_ingested"},
                {"key": "3", "label": "Edit Locked", "visibility_condition": "initialized_and_vile_not_ingested"},
            ]
        },
        "runtimeState": {
            "bootstrapMode": False,
            "tuilkitRuntimeMode": "fallback-not-ingested",
            "tuilkitIngested": False,
        },
    }

    result = execute("render_menu_visibility", payload)
    labels = [item["label"] for item in result["visibleItems"]]

    assert "Edit Locked" in labels
    assert "Edit" not in labels
